Let $\mathfrak{S}=(\Omega,S)$ be a rainbow, and let ${\mathcal A}=\langle \underline{s}\rangle_{s\in S}$ be the corresponding rainbow algebra. Then
		\begin{enumerate}[(a)]
			\item ${\mathcal A}$ is symmetric iff all basic relations of $\mathfrak{S}$ are symmetric;
			\item ${\mathcal A}$ is homogeneous iff $1_\Omega\in S$;
			\item ${\mathcal A}$ is regular iff all basic relations of $\mathfrak{S}$ are regular.
		\end{enumerate}

Each of the following holds:
		\begin{enumerate}[(a)]
			\item The transpose permutation $\tau$ belongs to the center of $\mathsf{JAut}({\mathfrak  S})$;
			\item For any $\Phi\leq \mathsf{JAut}({\mathfrak  S})$ and $s\in S$ the relation $\Phi(s):=\bigcup_{\phi\in\Phi}\phi(s)$ is either symmetric or anti-symmetric;
			\item For any $\Phi\leq \mathsf{JAut}({\mathfrak  S})$, $\bigl(\Omega,\{\Phi(s)\mid s\in S\}\bigr)$ is a Jordan configuration\xspace.
		\end{enumerate}

\label{loop}
		The magma $(S,\diamond)$ has the following properties
		\begin{enumerate}[(a)]
			\item \label{loop_a} $1_\Omega$ is the neutral element of $(S,\diamond)$;
			\item \label{loop_b} $\forall_{a\in S}\ a^{t}\diamond a =1_\Omega$;
			\item \label{loop_c} $\forall_{a,b\in S}\ a^{t}\diamond (a\diamond b)=b$;
			\item \label{loop_d} $\forall_{a,b\in S}$ the equation $x\diamond a = b$ has a unique solution $x\in S$.
		\end{enumerate}

\label{part} 
		Let $u,v\in S$, and let $\mathfrak a:=\mathfrak a({u,v})$ and $\overline{\mathfrak a}:=S\setminus \mathfrak a$. Then the following hold:
        \begin{enumerate}[(a)]
            \item $\ell_{u\diamond v} = \ell_u \ell_v 1_{\mathfrak a} \cup \ell_v \ell_u 1_{\overline{\mathfrak a}}$; in particular, $\ell_{u\diamond v} \subseteq \ell_u \ell_v \cup \ell_v \ell_u$.
            \item The set $\mathfrak a$ is invariant with respect to  $\ell_u$ and $\ell_v$.
        \end{enumerate}

\label{loop-prop} Let $L=L(G,*,g_0)$ be as above. Then 
		\begin{enumerate}[(a)]
			\item The map $x\mapsto x^*$ is an anti-automorphism of $G$;
			\item $Z(L)=Z(G)\times \{0\}$;
			\item $Z(L)$ coincides with the right and left nucleus of $L$.
		\end{enumerate}

\label{WL-loop}
		Let	$(S,\diamond)$ be a loop, and let $G\le Sym(S)$ be the subgroup generated by $\{\ell_s\}_{s\in S}$. Then $C_{{\sf Sym }(S)}(G)$                      
		coincides with the subgroup   $\widehat{N}_\rho:=\{r_s\}_{s\in N_\rho}$ of ${\sf Sym }(S)$, where $N_\rho$ is the right nucleus of $(S,\diamond)$.

\label{jaut}
		Let $\mathfrak{C}=(\Omega,C)$ be the $2$-orbit configuration of a semiregular subgroup $H\leq{\sf Sym }(\Omega)$. Then 
		\begin{enumerate}[(a)]
			\item $\mathfrak{C}\cong (\Omega_1,C\mathord{\upharpoonright}_{\Omega_1})\otimes \mathfrak{D}_k$ where $\Omega_1$ is an $H$-orbit, $k$ is the number of $H$-orbits on $\Omega$, and $\mathfrak{D}_k$ is the discrete configuration on $[k]:=\{1,\dots,k\}$.
			\item $\mathsf{JAut}(\mathfrak{C})=\mathsf{TAut}(\mathfrak{C})$.
		\end{enumerate}
